declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    Mode : BOOL;
    ForwardButton : BOOL;
    ReverseButton : BOOL;
    SensorA : BOOL;
    SensorB : BOOL;
    SensorC : BOOL;
    ButtonA : BOOL;
    ButtonB : BOOL;
    ButtonC : BOOL;
END_VAR
VAR_OUTPUT
    MotorForward : BOOL;
    MotorReverse : BOOL;
    CompletionLight : BOOL;
END_VAR
VAR
    step : INT;
END_VAR

implementation:
MotorForward := FALSE;
MotorReverse := FALSE;
CompletionLight := FALSE;

IF Mode THEN

    CASE step OF
        0:

            IF SensorA AND ButtonA THEN
                step := 1;
                MotorForward := TRUE;
            END_IF
        1:

            MotorForward := TRUE;
            IF SensorB THEN
                MotorForward := FALSE;
                step := 2;
            END_IF
        2:
            IF SensorB AND ButtonB THEN
                step := 3;
                MotorForward := TRUE;
            END_IF
        3:
            MotorForward := TRUE;
            IF SensorC THEN
                MotorForward := FALSE;
                step := 4;
            END_IF
        4:

            IF SensorC AND ButtonC THEN
                CompletionLight := TRUE;
                step := 5;
            END_IF
        5:

            CompletionLight := SensorC;
            IF NOT SensorC THEN
                step := 0;
            END_IF
    ELSE
        step := 0;
    END_CASE
ELSE

    step := 0;
    IF ForwardButton AND NOT ReverseButton THEN
        MotorForward := TRUE;
    END_IF
    IF ReverseButton AND NOT ForwardButton THEN
        MotorReverse := TRUE;
    END_IF
END_IF
